<?php
    $users=$db->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY id')->fetchAll();
    $editing=null;foreach($users as $u)if((int)$u['id']===(int)($_GET['id']??0))$editing=$u; ?>
    <div class="panel admin-users-panel"><div class="panel-heading"><div class="compact-heading"><h2>Equipe do portal</h2><details class="compact-help"><summary aria-label="Ajuda sobre funções de usuários">?</summary><div class="compact-help-content">Redator: edita seus rascunhos. Editor: publica e gerencia notícias. Administrador: gerencia também usuários, configurações e backups.</div></details><span class="muted tiny"><?= count($users) ?> conta(s)</span></div><?php if($editing): ?><a class="btn primary small" href="<?=h(admin_link('users'))?>#edit-user">+ Novo</a><?php else: ?><button type="button" class="btn primary small" data-admin-reveal="edit-user">+ Novo</button><?php endif; ?></div>
    <div class="table-wrap admin-users-wrap"><table class="admin-users-table"><thead><tr><th>Nome e e-mail</th><th>Função</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td data-label="Conta" class="users-identity"><strong><?= h($u['name']) ?></strong><small class="caption-hint"><?= h($u['email']) ?></small></td><td data-label="Função" class="users-role"><?= h(role_label($u['role'])) ?></td><td data-label="Status" class="users-status"><span class="health-mark <?= $u['active']?'good':'neutral' ?>"><?= $u['active']?'Ativo':'Desativado' ?></span></td><td data-label="Ações" class="action-cell users-actions"><a class="btn outline small" href="<?= h(admin_link('users')) ?>&id=<?= (int)$u['id'] ?>#edit-user">Editar</a><?php if((int)$u['id']!==(int)$me['id']): ?><form method="post" action="<?= h(admin_link('toggle_user')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button type="submit" class="btn outline small <?= $u['active']?'users-disable':'' ?>" data-confirm="Alterar acesso deste usuário?"><?= $u['active']?'Desativar':'Ativar' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
    <details class="panel form-panel admin-collapsible-form admin-user-form" id="edit-user" <?= $editing?'open':'' ?>><summary><?= $editing?'Editar usuário':'Adicionar usuário' ?></summary><form method="post" action="<?= h(admin_link('save_user')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><div class="form-grid"><label>Nome<input name="name" maxlength="100" required value="<?= h($editing['name']??'') ?>"></label><label>E-mail de acesso<input name="email" type="email" maxlength="190" autocomplete="off" required value="<?= h($editing['email']??'') ?>"></label><label>Função<select name="role"><?php foreach(['admin','editor','author'] as $role): ?><option value="<?= h($role) ?>" <?= selected($editing['role']??'author',$role) ?>><?= h(role_label($role)) ?></option><?php endforeach; ?></select></label><label><?= $editing?'Nova senha (opcional)':'Senha inicial (mín. 10 caracteres)' ?><input type="password" name="password" autocomplete="new-password" minlength="10" <?= $editing?'':'required' ?>></label></div><button class="btn primary">Salvar usuário</button></form></details>
